// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    Caller caller;

    function setUp() public { c = new ModifierEntrancy(); caller = new Caller(); }

    function testFuzz_property(uint256 seed) public {
        // admissible: any seed; caller is a valid Bank-compatible counterparty
        bool ok = caller.tryAirDrop(c, seed);
        assertTrue(ok);
    }
}

contract Caller {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }

    function tryAirDrop(ModifierEntrancy c, uint256 seed) external returns (bool) {
        seed; // keep fuzzer param admissible
        try c.airDrop() { return true; } catch { return false; }
    }
}
